import type { WebSearchOperations, WebSearchResult } from "./web-search.ts";

/** Exa's hosted search endpoint. */
export const EXA_SEARCH_ENDPOINT = "https://api.exa.ai/search";

/** Host of {@link EXA_SEARCH_ENDPOINT}, for the sandbox network allowlist. */
export const EXA_SEARCH_HOST = "api.exa.ai";

/** Exa's own default is 10; matching it keeps an unconfigured session predictable. */
export const DEFAULT_EXA_RESULT_COUNT = 10;

/**
 * Snippet budget per result. Exa returns whole page text when asked, which is the
 * wrong unit for a search result -- ten full pages would dwarf every other tool
 * result in the context window. 800 characters is roughly a paragraph, enough for
 * the model to judge relevance and decide whether to spend a `web_fetch` on it.
 */
export const DEFAULT_EXA_SNIPPET_CHARACTERS = 800;

export interface ExaWebSearchOptions {
	/** Resolved key, never a `$VAR` reference -- resolution happens before this call. */
	apiKey: string;
	/** Override for an Exa-compatible endpoint. Defaults to {@link EXA_SEARCH_ENDPOINT}. */
	endpoint?: string;
	numResults?: number;
	snippetMaxCharacters?: number;
}

/** The subset of Exa's `/search` response this adapter reads. */
interface ExaSearchResult {
	title?: string | null;
	url?: string | null;
	text?: string | null;
}

interface ExaSearchResponse {
	results?: ExaSearchResult[] | null;
}

function isAbortError(error: unknown): boolean {
	return error instanceof Error && error.name === "AbortError";
}

function hostOf(endpoint: string): string {
	try {
		return new URL(endpoint).host;
	} catch {
		return endpoint;
	}
}

/**
 * Page text arrives with the source document's line structure intact. Collapsing it
 * to a single line costs nothing in meaning and keeps a ten-result list readable as
 * a list rather than ten wrapped blocks.
 */
function toSnippet(text: string | null | undefined, maxCharacters: number): string {
	if (!text) return "";
	const collapsed = text.replace(/\s+/g, " ").trim();
	return collapsed.length > maxCharacters ? collapsed.slice(0, maxCharacters) : collapsed;
}

function toWebSearchResults(payload: ExaSearchResponse, maxCharacters: number): WebSearchResult[] {
	const results: WebSearchResult[] = [];
	for (const result of payload.results ?? []) {
		const url = result?.url?.trim();
		// A result the model cannot cite or fetch is worse than one fewer result.
		if (!url) continue;
		results.push({ title: result.title?.trim() || url, url, snippet: toSnippet(result.text, maxCharacters) });
	}
	return results;
}

/**
 * Exa-backed `web_search` backend.
 *
 * Reaches the network through `globalThis.fetch` for the same reason `web_fetch`
 * does: that is the dispatcher `configureHttpDispatcher` made proxy-aware, so an
 * allowlisted host routes through the sandbox proxy and a disallowed one has no
 * route at all. Opening a raw socket here would sidestep a boundary this tool is
 * supposed to sit behind.
 */
export function createExaWebSearchOperations(options: ExaWebSearchOptions): WebSearchOperations {
	const apiKey = options.apiKey?.trim();
	if (!apiKey) {
		throw new Error("Exa web search requires an API key; none was resolved.");
	}
	const endpoint = options.endpoint ?? EXA_SEARCH_ENDPOINT;
	const host = hostOf(endpoint);
	const numResults = options.numResults ?? DEFAULT_EXA_RESULT_COUNT;
	const snippetMaxCharacters = options.snippetMaxCharacters ?? DEFAULT_EXA_SNIPPET_CHARACTERS;

	return {
		async search(query, signal) {
			let response: Response;
			try {
				response = await fetch(endpoint, {
					method: "POST",
					headers: { "content-type": "application/json", "x-api-key": apiKey },
					body: JSON.stringify({
						query,
						numResults,
						contents: { text: { maxCharacters: snippetMaxCharacters } },
					}),
					signal,
				});
			} catch (error) {
				if (isAbortError(error)) throw error;
				// `fetch failed` alone names neither the host nor the remedy. The sandbox
				// refusal wrapper's message, when it produced one, is preserved verbatim here.
				const detail = error instanceof Error ? error.message : String(error);
				throw new Error(`web_search request to ${host} failed: ${detail}`, { cause: error });
			}

			if (!response.ok) {
				// The body can echo request fields, so only the status is reported -- a
				// pasted-through body is how an API key ends up in a transcript.
				throw new Error(`web_search request to ${host} failed with HTTP ${response.status}.`);
			}

			const payload = (await response.json()) as ExaSearchResponse;
			return toWebSearchResults(payload, snippetMaxCharacters);
		},
	};
}

/**
 * Task 4.4 (web_search/web_fetch): these tools never implement or bypass the
 * sandbox boundary themselves -- they call `globalThis.fetch`, made proxy-aware by
 * `configureHttpDispatcher`'s `undici.EnvHttpProxyAgent` (see `core/http-dispatcher.ts`
 * and `web-fetch.test.ts`'s "delegates to globalThis.fetch" case). `EnvHttpProxyAgent`
 * always tunnels through `HTTP_PROXY`/`HTTPS_PROXY` via CONNECT, for both http and
 * https destinations -- which is exactly what `network-proxy.ts`'s server implements
 * (it 405s any non-CONNECT request). This file proves that CONNECT-tunnel mechanism
 * carries real request/response bytes end-to-end inside a genuine bwrap-sandboxed
 * child: an allowed host's tunnel relays a real HTTP exchange, a disallowed host's
 * does not, and a raw connection that ignores the proxy entirely (what a tool would
 * do if it opened its own socket instead of using fetch) still has no route at all --
 * `--unshare-net` does not care what a tool's own JS code intended to do.
 *
 * `network-allowlist.test.ts` already covers the CONNECT accept/reject decision at
 * the proxy-response-line level; this file is the same mechanism carried one layer
 * further, to actual HTTP data, and adds the bypass-attempt case.
 */
import { mkdtempSync, rmSync } from "node:fs";
import * as http from "node:http";
import type * as net from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
import { launchSandboxedCli } from "../../src/core/sandbox/cli-supervisor.ts";
import { createLinuxSandboxBackend } from "../../src/core/sandbox/linux-backend.ts";

function canEnforceLinuxSandbox(): boolean {
	return process.platform === "linux" && createLinuxSandboxBackend().status.kind === "enforced";
}

const directories: string[] = [];
afterEach(() => {
	for (const directory of directories.splice(0)) rmSync(directory, { force: true, recursive: true });
});

function workspace(): string {
	const directory = mkdtempSync(join(tmpdir(), "apex-sandbox-fetch-mechanism-"));
	directories.push(directory);
	return directory;
}

/**
 * Establishes a CONNECT tunnel through $HTTP_PROXY, then sends a real HTTP/1.1 GET
 * inside it and prints whatever comes back. Exits 0 only if the response contains
 * the marker text the test server sends -- proving actual bytes flowed, not just a
 * "200 Connection Established" proxy handshake.
 */
function fetchThroughProxyScript(port: number): string {
	return `
		const net = require("node:net");
		const url = new URL(process.env.HTTP_PROXY);
		const c = net.connect(Number(url.port), url.hostname, () => {
			c.write("CONNECT 127.0.0.1:${port} HTTP/1.1\\r\\nHost: 127.0.0.1:${port}\\r\\n\\r\\n");
		});
		let established = false;
		let buffer = "";
		c.on("data", (d) => {
			buffer += d.toString();
			if (!established) {
				if (!buffer.includes("200")) { process.exit(1); }
				established = true;
				c.write("GET / HTTP/1.1\\r\\nHost: 127.0.0.1:${port}\\r\\nConnection: close\\r\\n\\r\\n");
				buffer = "";
				return;
			}
			if (buffer.includes("MECHANISM_MARKER")) { process.exit(0); }
		});
		c.on("close", () => process.exit(1));
		c.on("error", () => process.exit(1));
	`;
}

/** Opens a raw socket straight to the test server, ignoring $HTTP_PROXY entirely -- the bypass-attempt case. */
function bypassProxyScript(port: number): string {
	return `
		const net = require("node:net");
		const c = net.connect(${port}, "127.0.0.1", () => {
			c.write("GET / HTTP/1.1\\r\\nHost: 127.0.0.1:${port}\\r\\nConnection: close\\r\\n\\r\\n");
		});
		c.on("data", (d) => process.exit(d.toString().includes("MECHANISM_MARKER") ? 0 : 1));
		c.on("error", () => process.exit(1));
		c.on("close", () => process.exit(1));
	`;
}

describe.skipIf(!canEnforceLinuxSandbox())(
	"task 4.4: the fetch-proxy mechanism web_fetch/web_search rely on, exercised inside a real sandboxed child",
	() => {
		let testServer: http.Server;
		let testServerPort: number;

		beforeAll(async () => {
			testServer = http.createServer((_req, res) => {
				res.writeHead(200, { "Content-Type": "text/plain" });
				res.end("MECHANISM_MARKER");
			});
			await new Promise<void>((resolvePromise) => {
				testServer.listen(0, "127.0.0.1", () => {
					testServerPort = (testServer.address() as net.AddressInfo).port;
					resolvePromise();
				});
			});
		});

		afterAll(async () => {
			if (testServer) {
				await new Promise<void>((resolvePromise) => testServer.close(() => resolvePromise()));
			}
		});

		it("relays a real HTTP response through the proxy for an allowed host", async () => {
			const code = await launchSandboxedCli({
				command: process.execPath,
				args: ["-e", fetchThroughProxyScript(testServerPort)],
				environment: {},
				workspace: workspace(),
				allowedHosts: ["127.0.0.1"],
			});
			expect(code).toBe(0);
		});

		it("never relays a response for a host absent from the allowlist", async () => {
			const code = await launchSandboxedCli({
				command: process.execPath,
				args: ["-e", fetchThroughProxyScript(testServerPort)],
				environment: {},
				workspace: workspace(),
				allowedHosts: ["example.com"],
			});
			expect(code).not.toBe(0);
		});

		it("a raw socket that ignores $HTTP_PROXY entirely -- what a tool using a bare socket instead of fetch would do -- still has no route, even to an allowed host", async () => {
			const code = await launchSandboxedCli({
				command: process.execPath,
				args: ["-e", bypassProxyScript(testServerPort)],
				environment: {},
				workspace: workspace(),
				// Allowed at the proxy layer; irrelevant here since --unshare-net removes
				// the direct route this script tries to use, before the proxy is ever reached.
				allowedHosts: ["127.0.0.1"],
			});
			expect(code).not.toBe(0);
		});
	},
);

import type { AgentToolResult } from "apex-code-agent-core";
import { type Static, Type } from "typebox";
import type { ApexToolDefinition } from "./contract.ts";
import { wrapToolDefinition } from "./tool-definition-wrapper.ts";

const webSearchSchema = Type.Object({
	query: Type.String({ description: "The search query." }),
});

export type WebSearchInput = Static<typeof webSearchSchema>;

export interface WebSearchResult {
	title: string;
	url: string;
	snippet: string;
}

export interface WebSearchDetails {
	results: WebSearchResult[];
}

export interface WebSearchOperations {
	search(query: string, signal?: AbortSignal): Promise<WebSearchResult[]>;
}

/**
 * No search vendor is wired into this repo (unlike web_fetch, which needs only an
 * HTTP GET). A deployment supplies its own provider via `WebSearchToolOptions`;
 * failing loudly here beats a silent no-op that would look like zero results.
 */
const unconfiguredWebSearchOperations: WebSearchOperations = {
	async search() {
		throw new Error(
			"web_search is not configured: no search provider was supplied. Pass WebSearchToolOptions.operations.",
		);
	},
};

function formatResults(results: WebSearchResult[]): string {
	if (results.length === 0) return "No results found.";
	return results.map((result) => `${result.title}\n${result.url}\n${result.snippet}`).join("\n\n");
}

export interface WebSearchToolOptions {
	operations?: WebSearchOperations;
}

export function createWebSearchToolDefinition(
	options?: WebSearchToolOptions,
): ApexToolDefinition<typeof webSearchSchema, WebSearchDetails> {
	const ops = options?.operations ?? unconfiguredWebSearchOperations;
	return {
		name: "web_search",
		label: "web_search",
		description: "Search the web and return a list of results.",
		parameters: webSearchSchema,
		contract: {
			capabilities: new Set(["net"]),
			permission: {
				defaultBehavior: "ask",
				// A query is not a generalizable rule (ruleForCall returns null); the only
				// rule content worth recognizing is a hand-authored blanket "*".
				matches: (ruleContent) => ruleContent === "*",
				describe: () => "Web search (any query)",
				ruleForCall: () => null,
			},
			context: { resultRecoverable: false, deferSchema: true },
			evidence: { emits: new Set(), capture: () => [] },
		},
		async execute(
			_toolCallId,
			{ query }: WebSearchInput,
			signal?: AbortSignal,
		): Promise<AgentToolResult<WebSearchDetails>> {
			const results = await ops.search(query, signal);
			return {
				content: [{ type: "text", text: formatResults(results) }],
				details: { results },
			};
		},
	};
}

export function createWebSearchTool(options?: WebSearchToolOptions) {
	return wrapToolDefinition(createWebSearchToolDefinition(options));
}

import { readStoredCredential } from "./auth-storage.ts";
import {
	getConfigValueEnvVarNames,
	isCommandConfigValue,
	isConfigValueConfigured,
	resolveConfigValue,
} from "./resolve-config-value.ts";
import type { WebSearchSettings } from "./settings-manager.ts";
import type { WebSearchOperations } from "./tools/web-search.ts";
import { createExaWebSearchOperations, EXA_SEARCH_HOST } from "./tools/web-search-exa.ts";

export type WebSearchProviderId = "exa";

/**
 * One entry per backend `web_search` can speak to.
 *
 * A table rather than a branch because the swap is the point: the `web_search` tool
 * owns the contract and the permission grammar, the backend owns nothing but an HTTP
 * call, and adding the second backend should be a row here rather than a new code
 * path through the resolver.
 */
interface WebSearchProviderDefinition {
	/**
	 * Config-value reference used when settings name no key. Held as a reference,
	 * never a literal: a resolved key must never reach a file the settings loader
	 * writes back.
	 */
	readonly defaultApiKeyReference: string;
	/** Host the sandbox must allow before this backend can reach anything. */
	readonly host: string;
	/** `auth.json` key holding a credential saved from the settings panel. */
	readonly credentialId: string;
	create(options: {
		apiKey: string;
		endpoint?: string;
		numResults?: number;
		snippetMaxCharacters?: number;
	}): WebSearchOperations;
}

const WEB_SEARCH_PROVIDERS: Record<WebSearchProviderId, WebSearchProviderDefinition> = {
	exa: {
		defaultApiKeyReference: "$EXA_API_KEY",
		host: EXA_SEARCH_HOST,
		credentialId: "exa",
		create: createExaWebSearchOperations,
	},
};

/**
 * Backend used when settings name none. `web_search` still reports itself
 * unconfigured unless this backend's key resolves, so the default selects which
 * credential is looked for, not whether the tool reaches the network.
 */
export const DEFAULT_WEB_SEARCH_PROVIDER: WebSearchProviderId = "exa";

function definitionFor(settings: WebSearchSettings | undefined): WebSearchProviderDefinition {
	return WEB_SEARCH_PROVIDERS[settings?.provider ?? DEFAULT_WEB_SEARCH_PROVIDER];
}

/** `auth.json` key holding a stored credential for the selected backend. */
function webSearchCredentialId(settings?: WebSearchSettings): string {
	return definitionFor(settings).credentialId;
}

/**
 * The reference stored by the settings panel, or undefined when nothing is saved.
 *
 * Whatever was saved stays a reference rather than being resolved here, so the one
 * resolution below covers a literal key, a `$VAR`, and a `!command` alike. An OAuth
 * credential under the same key is not an API key and is ignored rather than coerced.
 */
function storedApiKeyReference(settings: WebSearchSettings | undefined, authPath?: string): string | undefined {
	const credential = readStoredCredential(webSearchCredentialId(settings), authPath);
	if (credential?.type !== "api_key") return undefined;
	return credential.key?.trim() || undefined;
}

/**
 * Reject a literal secret configured in settings.
 *
 * `webSearch.apiKey` is read from project settings as well as global ones, and this
 * repository deliberately does not gitignore `<project>/.apex-code/` -- that directory
 * is meant to be versioned and shared with a team. A literal key written there would be
 * committed and handed to everyone who clones the repository.
 *
 * A reference (`$VAR`, `${VAR}`, `!command`) names where the secret lives without
 * containing it, so it is safe to commit. AGENTS.md already states that no credential
 * belongs in a file the settings loader writes; this makes that rule enforced rather
 * than documented. `auth.json` still accepts literals, because holding secrets outside
 * the repository is what the credential store is for.
 */
export function webSearchSettingsError(settings?: WebSearchSettings): string | undefined {
	const configured = settings?.apiKey?.trim();
	if (!configured) return undefined;
	if (isCommandConfigValue(configured)) return undefined;
	if (getConfigValueEnvVarNames(configured).length > 0) return undefined;
	// The value itself is never echoed: this message reaches the model, and from there a
	// transcript. Naming the setting is enough to act on.
	return `webSearch.apiKey must be a reference, not a literal key, because project settings are versioned and shared. Use "$EXA_API_KEY", "\${YOUR_VAR}", or "!your-command", and keep the secret in your environment or credential store.`;
}

/**
 * Pick one reference, then resolve it once.
 *
 * Order is explicit configuration, then saved credential, then ambient environment.
 * A user who just typed a key into the settings dialog expects it to beat a stale
 * export they have forgotten about, and an explicit `webSearch.apiKey` in settings is
 * a direct instruction that should beat both.
 */
function apiKeyReferenceFor(settings: WebSearchSettings | undefined, authPath?: string): string {
	// A refused literal falls through rather than being honoured, so a committed key is
	// inert instead of quietly working for whoever cloned the repository.
	const configured = webSearchSettingsError(settings) ? undefined : settings?.apiKey?.trim();
	return configured || storedApiKeyReference(settings, authPath) || definitionFor(settings).defaultApiKeyReference;
}

/**
 * The host `web_search` needs on the sandbox allowlist, or undefined when no
 * credential is configured for the selected backend.
 *
 * Deliberately checks whether the key *reference* resolves rather than resolving it:
 * the supervisor calls this on every launch, and a `!command` reference would
 * otherwise spawn a shell before the child even starts. That check is an environment
 * lookup for a `$VAR` reference and free for a command reference.
 */
export function resolveWebSearchHost(
	settings: WebSearchSettings | undefined,
	env?: Record<string, string>,
	authPath?: string,
): string | undefined {
	const definition = definitionFor(settings);
	return isConfigValueConfigured(apiKeyReferenceFor(settings, authPath), env) ? definition.host : undefined;
}

/**
 * Build the configured `web_search` backend, or undefined when no credential
 * resolves.
 *
 * Undefined leaves the tool on its unconfigured operations, which throw a
 * model-readable "not configured" error. That is deliberately not the same thing as
 * hiding the tool: a session that silently lacks `web_search` cannot tell the model
 * why, and the throw names the missing piece.
 */
/**
 * What to tell the model, and through it the user, when nothing is configured.
 *
 * Named here rather than in `web-search.ts` because only this module knows which
 * backend was selected and therefore which credential to name. The audience is a
 * person who asked the agent to search something, so it names the two things they
 * can actually do, not the SDK option an embedder would pass.
 */
export function unconfiguredWebSearchMessage(settings?: WebSearchSettings): string {
	const definition = definitionFor(settings);
	const variable = definition.defaultApiKeyReference.replace(/^\$/, "");
	return `web_search has no API key configured. Set ${variable} in the environment, or run /settings and add a ${definition.credentialId} key.`;
}

/**
 * A `web_search` backend that resolves its credential on each call.
 *
 * The session builds its tool registry once, at construction, so operations captured
 * there would pin whatever was configured at startup. A key saved from the settings
 * panel would then appear to save and do nothing until restart, which is worse than
 * having no settings row at all. Resolving per call costs one small file read and
 * keeps `resolveConfigValue`'s cache for command references.
 */
export function createDeferredWebSearchOperations(
	readSettings: () => WebSearchSettings | undefined,
	authPath?: string,
): WebSearchOperations {
	return {
		async search(query, signal) {
			const settings = readSettings();
			// Reported ahead of the unconfigured message: "no key" and "your key is in the
			// wrong place" need different fixes.
			const settingsError = webSearchSettingsError(settings);
			if (settingsError) throw new Error(settingsError);
			const operations = resolveWebSearchOperations(settings, undefined, authPath);
			if (!operations) throw new Error(unconfiguredWebSearchMessage(settings));
			return operations.search(query, signal);
		},
	};
}

export function resolveWebSearchOperations(
	settings: WebSearchSettings | undefined,
	env?: Record<string, string>,
	authPath?: string,
): WebSearchOperations | undefined {
